--- i/internal/oci/registry.go
+++ w/internal/oci/registry.go
@@ -51,11 +51,14 @@ const (
 	SourceRegistry StatusSource = iota
 	// SourceToken is the Bearer token endpoint.
 	SourceToken
+	// SourceManagementAPI is a registry manager's own REST API (Nexus
+	// /service/rest), not the distribution v2 API.
+	SourceManagementAPI
 )

-// StatusError is a registry or token endpoint answering with a non-success
-// status. Failures that are not a status (unreadable body, missing realm, no
-// token field) are plain errors.
+// StatusError is a registry, token or management API endpoint answering with a
+// non-success status. Failures that are not a status (unreadable body, missing
+// realm, no token field) are plain errors.
 type StatusError struct {
 	Code   int
 	Source StatusSource
@@ -72,6 +75,8 @@ func (e *StatusError) Error() string {
 	switch {
 	case e.Source == SourceToken:
 		return fmt.Sprintf("token endpoint returned %d", e.Code)
+	case e.Source == SourceManagementAPI:
+		return fmt.Sprintf("management API returned %d", e.Code)
 	case e.unexpectedChallenge:
 		return fmt.Sprintf("unexpected auth challenge: %s", e.Challenge)
 	}
diff --git i/internal/registrymgr/nexus.go w/internal/registrymgr/nexus.go
index 7323c33c..64de5e82 100644
--- i/internal/registrymgr/nexus.go
+++ w/internal/registrymgr/nexus.go
@@ -1,6 +1,7 @@
 package registrymgr

 import (
+	"bytes"
 	"context"
 	"encoding/json"
 	"errors"
@@ -32,6 +33,14 @@ type NexusDetector struct{}
 // figure follows the reasoning of the catalog page cap and is not measured.
 const maxNexusResponse = 1 << 20

+// errEmptyReply and errNoRepositoryType mark a 200 reply that is not a
+// repository document. Both fail the discovery: reading either as "not a group"
+// would be cached (D23) and erase the members last known.
+var (
+	errEmptyReply       = errors.New("empty reply")
+	errNoRepositoryType = errors.New("reply names no repository type")
+)
+
 // nexusHTTPClient refuses a redirect to another origin, so the account of the
 // registry is never sent to a host it was not given for.
 var nexusHTTPClient = &http.Client{Timeout: 8 * time.Second, CheckRedirect: oci.RefuseOffOriginRedirect}
@@ -103,6 +112,10 @@ func (n *NexusDetector) fetchRepoMeta(ctx context.Context, host, repoName string
 		log.Printf("INFO [registrymgr/nexus] meta unreachable %q: %v", endpoint, err)
 		return "", "", nil, fmt.Errorf("reading %s: %w", endpoint, err)
 	}
+	if len(bytes.TrimSpace(body)) == 0 {
+		log.Printf("INFO [registrymgr/nexus] meta %q: empty reply", repoName)
+		return "", "", nil, fmt.Errorf("parsing the reply from %s: %w", endpoint, errEmptyReply)
+	}
 	var result struct {
 		Type   string `json:"type"`
 		Format string `json:"format"`
@@ -119,6 +132,11 @@ func (n *NexusDetector) fetchRepoMeta(ctx context.Context, host, repoName string
 		log.Printf("INFO [registrymgr/nexus] meta parse error for %q: %v", repoName, err)
 		return "", "", nil, fmt.Errorf("parsing the reply from %s: %w", endpoint, err)
 	}
+	if result.Type == "" {
+		// Valid JSON that is not a repository document: `{}`, `null`.
+		log.Printf("INFO [registrymgr/nexus] meta %q: reply names no repository type", repoName)
+		return "", "", nil, fmt.Errorf("parsing the reply from %s: %w", endpoint, errNoRepositoryType)
+	}
 	log.Printf("INFO [registrymgr/nexus] meta %q: type=%s format=%s", repoName, result.Type, result.Format)

 	// Collect memberNames from whichever field Nexus populated.
@@ -213,7 +231,9 @@ func memberAddress(dockerURL, memberName string) (url, prefix string) {
 	return host, memberName
 }

-// nexusGET performs an authenticated GET and returns the response body.
+// nexusGET performs an authenticated GET and returns the response body. A status
+// other than 200 is a *oci.StatusError from the management API: the code only, no
+// status line, body or header. A context error stays a context error.
 func (n *NexusDetector) nexusGET(ctx context.Context, endpoint string, info RegistryInfo) ([]byte, error) {
 	req, err := http.NewRequestWithContext(ctx, "GET", endpoint, nil)
 	if err != nil {
@@ -230,10 +250,15 @@ func (n *NexusDetector) nexusGET(ctx context.Context, endpoint string, info Regi
 	}
 	defer func() { _ = resp.Body.Close() }()
 	if resp.StatusCode != http.StatusOK {
-		return nil, fmt.Errorf("HTTP %d", resp.StatusCode)
+		return nil, &oci.StatusError{Code: resp.StatusCode, Source: oci.SourceManagementAPI}
 	}
 	body, err := oci.ReadAllLimited(resp.Body, maxNexusResponse)
 	if err != nil {
+		// Which error net/http gives a body cut by a cancel varies: report the
+		// context's own.
+		if ctxErr := ctx.Err(); ctxErr != nil {
+			return nil, fmt.Errorf("read Nexus response: %w", ctxErr)
+		}
 		return nil, fmt.Errorf("read Nexus response: %w", err)
 	}
 	return body, nil

tools.description:
Work items -- issues, tasks and epics.

Actions:
  list (no required params; optional project_id, pql, order_by, per_page, cursor, expand, fields, external_id, external_source) -- omit project_id to search the whole workspace;
  list_archived (project_id; optional pql, order_by, per_page, cursor, expand, fields, external_id, external_source);
  retrieve (project_id, workitem_id; optional expand, fields, external_id, external_source, order_by);
  retrieve_by_identifier (workitem_identifier; optional expand, fields, external_id, external_source, order_by) -- identifier is PROJECT-N, e.g. ENG-42;
  search (query; optional expand, fields, external_id, external_source, order_by);
  count (no required params; optional project_id, pql, group_by, sub_group_by) -- counts the whole workspace unless project_id narrows it;
  create (project_id, name; optional assignees, labels, type_id, point, description_html, description_stripped, priority, start_date, target_date, sort_order, is_draft, parent, state, estimate_point, external_source, external_id);
  update (project_id, workitem_id; optional name, assignees, labels, type_id, point, description_html, description_stripped, priority, start_date, target_date, sort_order, is_draft, parent, state, estimate_point, external_source, external_id) -- only the fields you pass are changed;
  delete (project_id, workitem_id);
  archive (project_id, workitem_id; optional archive) -- archive defaults to true; pass archive=false to unarchive. Only completed or cancelled items can be archived;
  manage_assignee (project_id, workitem_id; optional add_user_id, remove_user_id) -- each takes one id or several; the list is merged, not replaced, and removals apply first;
  manage_label (project_id, workitem_id; optional add_label_id, remove_label_id) -- each takes one id or several; the list is merged, not replaced, and removals apply first.

priority: urgent, high, medium, low, none.
UUID fields (assignees, labels, state, parent, type_id) need UUIDs -- list the relevant resource first if you only have a name.
description_stripped is plain text and is wrapped into HTML on save; description_html wins if both are given.
To clear a field on update: assignees=[] or labels=[], and start_date=null or target_date=null. A field you leave out is not changed.
fields is a sparse fieldset: use `project`, not project_id, and `description_html`, not description.
count group_by and sub_group_by accept: state_id, state__group, priority, project_id, type_id, labels__id, assignees__id, issue_module__module_id, release_work_items__release_id, cycle_id, milestone_id, created_by, target_date, start_date. These are grouping keys only -- they are not PQL filter fields, and filtering on state__group is rejected.

Comments on a work item.

Actions:
  list (project_id, workitem_id; optional cursor, per_page);
  retrieve (project_id, workitem_id, comment_id);
  create (project_id, workitem_id, comment_html; optional access, external_source, external_id);
  update (project_id, workitem_id, comment_id; optional comment_html, access, external_source, external_id);
  delete (project_id, workitem_id, comment_id).

comment_html is HTML, e.g. '<p>Looks good.</p>'. access is INTERNAL or EXTERNAL.
To mention someone, write @[<user uuid>] inline -- '<p>@[<user uuid>] can you review?</p>' -- and the chip and the notification are generated for you. A bare @name is ordinary text that notifies nobody. The id must belong to a member of the work item's project; `member list_project` resolves a name to one. Mentions read back in the same form.

