			var formatHits atomic.Int32
			info, _ := nexusServer(t, func(w http.ResponseWriter, r *http.Request) {
				if strings.Contains(r.URL.Path, "/group/") {
					formatHits.Add(1)
					_, _ = io.WriteString(w, body)
